package com.geekmall.search;
import com.fasterxml.jackson.databind.*;import com.geekmall.common.api.BusinessException;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Component;import java.net.URI;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.util.*;
@Component class ElasticsearchGateway{private final HttpClient http=HttpClient.newBuilder().build();private final ObjectMapper mapper;private final String base;static final String INDEX="geek-products-v1";ElasticsearchGateway(ObjectMapper m,@Value("${geek.elasticsearch-url}")String b){mapper=m;base=b;}
 void ensureIndex(){try{var head=send("HEAD","/"+INDEX,null);if(head.statusCode()==404){String mapping="""
 {"mappings":{"properties":{"title":{"type":"text","fields":{"keyword":{"type":"keyword"}}},"subtitle":{"type":"text"},"categoryId":{"type":"long"},"categoryName":{"type":"keyword"},"brandId":{"type":"long"},"brandName":{"type":"keyword"},"shopId":{"type":"long"},"shopName":{"type":"keyword"},"minPrice":{"type":"scaled_float","scaling_factor":100},"maxPrice":{"type":"scaled_float","scaling_factor":100},"salesCount":{"type":"long"},"rating":{"type":"scaled_float","scaling_factor":100},"saleStatus":{"type":"keyword"},"auditStatus":{"type":"keyword"},"attributes":{"type":"nested","properties":{"name":{"type":"keyword"},"value":{"type":"keyword"}}}}}}
 """;check(send("PUT","/"+INDEX,mapping));}}catch(Exception e){throw unavailable(e);}}
 void index(String id,JsonNode doc){try{check(send("PUT","/"+INDEX+"/_doc/"+id,mapper.writeValueAsString(doc)));}catch(Exception e){throw unavailable(e);}}
 void delete(String id){try{var r=send("DELETE","/"+INDEX+"/_doc/"+id,null);if(r.statusCode()>=300&&r.statusCode()!=404)check(r);}catch(Exception e){throw unavailable(e);}}
 JsonNode search(Map<String,Object> params){try{String keyword=String.valueOf(params.getOrDefault("keyword","")).trim();List<Object> filters=new ArrayList<>();filters.add(Map.of("term",Map.of("saleStatus","ON_SALE")));if(params.get("categoryId")!=null)filters.add(Map.of("term",Map.of("categoryId",params.get("categoryId"))));if(params.get("brandIds")instanceof List<?>ids&&!ids.isEmpty())filters.add(Map.of("terms",Map.of("brandId",ids)));if(params.get("shopId")!=null)filters.add(Map.of("term",Map.of("shopId",params.get("shopId"))));if(params.get("priceMin")!=null||params.get("priceMax")!=null){Map<String,Object>range=new LinkedHashMap<>();if(params.get("priceMin")!=null)range.put("gte",params.get("priceMin"));if(params.get("priceMax")!=null)range.put("lte",params.get("priceMax"));filters.add(Map.of("range",Map.of("minPrice",range)));}Object must=keyword.isBlank()?Map.of("match_all",Map.of()):Map.of("multi_match",Map.of("query",keyword,"fields",List.of("title^4","subtitle^2","brandName","categoryName","shopName"),"fuzziness","AUTO"));Map<String,Object>body=new LinkedHashMap<>();body.put("query",Map.of("bool",Map.of("must",must,"filter",filters)));int page=((Number)params.getOrDefault("page",1)).intValue(),size=((Number)params.getOrDefault("pageSize",20)).intValue();body.put("from",(page-1)*size);body.put("size",size);String sort=String.valueOf(params.getOrDefault("sort","comprehensive"));if("priceAsc".equals(sort))body.put("sort",List.of(Map.of("minPrice","asc")));else if("priceDesc".equals(sort))body.put("sort",List.of(Map.of("minPrice","desc")));else if("sales".equals(sort))body.put("sort",List.of(Map.of("salesCount","desc")));else if("rating".equals(sort))body.put("sort",List.of(Map.of("rating","desc")));body.put("aggs",Map.of("brands",Map.of("terms",Map.of("field","brandId","size",30)),"categories",Map.of("terms",Map.of("field","categoryId","size",30))));var r=send("POST","/"+INDEX+"/_search",mapper.writeValueAsString(body));check(r);return mapper.readTree(r.body());}catch(Exception e){if(e instanceof BusinessException b)throw b;throw unavailable(e);}}
 List<String> suggest(String prefix){if(prefix==null||prefix.isBlank())return List.of();try{var q=Map.of("size",8,"_source",List.of("title"),"query",Map.of("match_phrase_prefix",Map.of("title",Map.of("query",prefix,"max_expansions",20))));var r=send("POST","/"+INDEX+"/_search",mapper.writeValueAsString(q));check(r);List<String>out=new ArrayList<>();r=HttpResponseStub.of(r);for(JsonNode h:mapper.readTree(r.body()).path("hits").path("hits"))out.add(h.path("_source").path("title").asText());return out.stream().distinct().toList();}catch(Exception e){throw unavailable(e);}}
 long count(){try{var r=send("GET","/"+INDEX+"/_count",null);check(r);return mapper.readTree(r.body()).path("count").asLong();}catch(Exception e){throw unavailable(e);}}
 private HttpResponse<String>send(String method,String path,String body)throws Exception{var b=HttpRequest.newBuilder(URI.create(base+path)).header("Content-Type","application/json");b.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body,StandardCharsets.UTF_8));return http.send(b.build(),HttpResponse.BodyHandlers.ofString());}
 private void check(HttpResponse<String>r){if(r.statusCode()<200||r.statusCode()>=300)throw new BusinessException("SR50301","Elasticsearch 请求失败：HTTP "+r.statusCode());}private BusinessException unavailable(Exception e){return new BusinessException("SR50301","搜索服务暂不可用："+e.getClass().getSimpleName());}
 private static final class HttpResponseStub{static HttpResponse<String>of(HttpResponse<String>r){return r;}}
}
